{
  "concepts": [
    {
      "conditions": [],
      "definition": "A durable authoritative work record that survives sessions and work waves. Its carrier defaults to one Markdown file; its identity and authority are distinct from a run-scoped execution contract.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":85,
          "quote":"ticket survives sessions and work waves;",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F1.%20Work%20carriers%2FExecution%20contracts",
          "start_line":82
        },
        {
          "end_line":330,
          "quote":"Each ticket has one durable authoritative record; the default carrier is\none markdown file.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FOne%20durable%20record%20per%20ticket",
          "start_line":329
        }
      ],
      "key":"ticket",
      "label":"Ticket"
    },
    {
      "conditions": [],
      "definition": "The current admitted execution function for one run, derived from a ticket, a sprint manifest with an included ticket or iteration entry, or drafted during intake when no durable or sprint-local work identity is required. Drafting, admission, rejection and supersession remain distinct states.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":85,
          "quote":"An execution contract is the run-scoped\nadmitted work surface",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F1.%20Work%20carriers%2FExecution%20contracts",
          "start_line":78
        },
        {
          "end_line":683,
          "quote":"(drafted, admitted, rejected, superseded).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F5.%20From%20carrier%20to%20execution%2FExecution%20contract%20admission",
          "start_line":683
        }
      ],
      "key":"execution_contract",
      "label":"Execution contract"
    },
    {
      "conditions": [],
      "definition": "A subordinate closure-bearing work claim with stable identity, bounded claim, relevant dependencies, current state, required evidence and an explicit relation to ticket closure. Several milestones may belong to one ticket.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":106,
          "quote":"Each milestone has stable identity, a bounded claim,\nrelevant dependencies, current state, required evidence, and an explicit\nrelation to ticket closure (P3).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F1.%20Work%20carriers%2FMilestones%20and%20phase-scoped%20truth%20%28UP-006%29",
          "start_line":104
        }
      ],
      "key":"milestone",
      "label":"Milestone"
    },
    {
      "conditions": [],
      "definition": "Product-definition locations for work carriers: ticketing.goals locates the epic layer; optional ticketing.sprints.root locates bounded execution batches and sprint-close review; ticketing.tickets.lanes.backlog, .active and .completed locate ticket authority; ticketing.comments.root locates discussion and publication. The definition locates carriers without owning their ticket or comment content.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":157,
          "quote":"The definition locates these carriers and\ndoes not own their ticket or comment content.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F2.%20Layout%20and%20authority%2FBindings%20and%20projections",
          "start_line":156
        }
      ],
      "key":"carrier_binding",
      "label":"Work-carrier binding"
    },
    {
      "conditions": [],
      "definition": "A generated board or other derived presentation of work authority. Comments, dashboards, registers, indexes and summaries are projections; visibility, repetition and recency do not confer authority.",
      "exceptions": [
        "A board becomes the ticket authority only through explicit product-definition rebinding with no rival remaining."
      ],
      "grounding": [
        {
          "end_line":163,
          "quote":"that board is a projection only and does not become the source of truth\nunless the product definition explicitly rebinds the ticket authority to\nthat carrier and no rival remains (§7).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F2.%20Layout%20and%20authority%2FBindings%20and%20projections",
          "start_line":161
        },
        {
          "end_line":1269,
          "quote":"Comments,\ndashboards, registers, indexes and generated summaries are projections",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FOne-truth%20state%20projection%20and%20drift%20refusal%20%28UP-009%29",
          "start_line":1267
        }
      ],
      "key":"work_projection",
      "label":"Work-state projection"
    },
    {
      "conditions": [],
      "definition": "The one durable record of a sprint, whose lifetime covers one bounded execution batch and its close review. A local Markdown file is the default carrier.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":84,
          "quote":"a sprint survives one bounded\nexecution batch and its close review;",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F1.%20Work%20carriers%2FExecution%20contracts",
          "start_line":82
        },
        {
          "end_line":185,
          "quote":"Each sprint has one durable manifest record; the default carrier is one\nmarkdown file.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F3.%20Sprint%20rules%2FOne%20durable%20record%20per%20sprint",
          "start_line":183
        }
      ],
      "key":"sprint_manifest",
      "label":"Sprint manifest"
    },
    {
      "conditions": [],
      "definition": "Declared sprint states minimally comprise active, closing, closed and superseded. Active admits iteration within the boundary; closing freezes new iteration during review and paydown classification; closed denotes finished review with all remaining debt accepted, ticketed, repriced or removed; superseded denotes replacement of an incorrect boundary by a new authority surface, sprint or ticket set.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":217,
          "quote":"The minimum sprint status model is `active`, `closing`, `closed` and\n`superseded`",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F3.%20Sprint%20rules%2FSprint%20status",
          "start_line":211
        }
      ],
      "key":"sprint_status",
      "label":"Sprint status"
    },
    {
      "conditions": [],
      "definition": "A result for one reviewed item, separate from the core assessment it consumes. For the predicate that the item is accepted as compliant under sprint authority: accepted maps to accept/satisfied; local_paydown maps to local_repair/falsified; design_reframe, requirement_reprice and product_reprice map to re_enter/invalid_basis; remove maps to falsified with no matching disposition. Debt outcomes map correspondingly: accepted to accept/satisfied, ticketed to local_repair/falsified, repriced to re_enter/invalid_basis, removed to falsified with no matching disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":294,
          "quote":"Each classification\ntakes exactly one core value, for the predicate \"the reviewed item is\naccepted as compliant under the sprint authority\"",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F3.%20Sprint%20rules%2FClose%20review",
          "start_line":291
        },
        {
          "end_line":316,
          "quote":"accepted matches `accept` (`satisfied`), ticketed\nmatches `local_repair` (`falsified`), removed takes `falsified` with no\nmatching disposition, and repriced matches `re_enter`\n(`invalid_basis`)",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F3.%20Sprint%20rules%2FClose%20review",
          "start_line":313
        }
      ],
      "key":"sprint_close_result",
      "label":"Sprint-close classification and debt outcome"
    },
    {
      "conditions": [],
      "definition": "The kind of work record. The minimum common types are feature, bug, spike and chore; the source expects this default set to suffice for most cases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":412,
          "quote":"The minimum common set of ticket types is `feature`, `bug`, `spike` and\n`chore`.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FTypes",
          "start_line":410
        }
      ],
      "key":"ticket_type",
      "label":"Ticket type"
    },
    {
      "conditions": [],
      "definition": "The execution or migration discipline governing a ticket, orthogonal to its type and change class. The minimum categories are ordinary and implementation_migration; feature, bug, spike and chore may each carry either.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":421,
          "quote":"category answers what execution or migration\ndiscipline governs the ticket",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FCategory",
          "start_line":418
        }
      ],
      "key":"ticket_category",
      "label":"Ticket category"
    },
    {
      "conditions": [],
      "definition": "The intake-triage declaration of lawful constitutional re-entry, distinct from ticket type and execution discipline. Named classes include goal_reprice, intent_reprice, product_reprice, requirement_reprice, design_reframe and realization_refactor. Common pairings are illustrative: feature with the first five, bug with requirement_reprice/design_reframe/realization_refactor, chore with design_reframe/realization_refactor; a spike still carries its current triage class.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":452,
          "quote":"change class answers where the change lawfully\nre-enters the constitutional chain.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FChange%20class",
          "start_line":449
        }
      ],
      "key":"change_class",
      "label":"Change class"
    },
    {
      "conditions": [],
      "definition": "Intake classification consuming the computed result for the declared owner/layer traversal, complete relevant public membership and value delta, accepted-design scope and trace coverage, and rule-determined treatment. The owning carrier references that exact result and its residuals.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":476,
          "quote":"The owning work carrier references that\nexact result and its residuals; a new role does not repeat an unchanged\nwalk",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FUpward%20propagation%20check",
          "start_line":474
        }
      ],
      "key":"intake_triage",
      "label":"Intake triage and upward propagation"
    },
    {
      "conditions": [],
      "definition": "Declared ticket states minimally comprise backlog, active and completed. Their corresponding lanes mean accepted durable work outside current execution focus, the current bounded execution set, and closed work retained as history. State labels are not evaluation results.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":521,
          "quote":"The minimum ticket status model is `backlog`, `active` and `completed`.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FStatus",
          "start_line":519
        },
        {
          "end_line":546,
          "quote":"`backlog`\nis accepted durable work that should remain visible but is not part of the\ncurrent execution focus; `active` is the current bounded execution set;\n`completed` is closed work retained as history.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FLanes",
          "start_line":543
        }
      ],
      "key":"ticket_state",
      "label":"Ticket status and lane"
    },
    {
      "conditions": [],
      "definition": "One admitted upstream work item with multiple build-tenant execution lines. Upstream authority and tenant-local tickets have distinct identities and lifecycles. The three lawful cases are upstream-only with no tenant duplicate yet, single-tenant with no sibling required, and multi-tenant with one upstream authority ticket plus one suffixed ticket per tenant execution line. The referenced build-tenancy context is urn:stdo:bounded-context:build-tenancy; this member owns its work-item/lifecycle relation, not tenant identity or realisation meaning.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":350,
          "quote":"A multi-build-tenant work item is one admitted upstream work item with more\nthan one build-tenant execution line.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FMulti-build-tenant%20independence",
          "start_line":348
        }
      ],
      "key":"multi_build_tenant_work",
      "label":"Multi-build-tenant work item"
    },
    {
      "conditions": [],
      "definition": "A ticket for governed replacement of one implementation truth path by another across producers, consumers, projections and proof surfaces. Examples include replacing a tracker/read-model authority, introducing a public interface requiring producer and consumer migration, or removing an authoritative bridge or compatibility facade.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":428,
          "quote":"a governed\nreplacement of one implementation truth path with another across producers,\nconsumers, projections and proof surfaces",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F4.%20Ticket%20rules%2FCategory",
          "start_line":422
        }
      ],
      "key":"migration_ticket",
      "label":"Implementation migration ticket"
    },
    {
      "conditions": [],
      "definition": "A declared migration-strategy field with values inside_out_hard_break and fundamental_re_adoption; the value is a carrier state, not a core result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":792,
          "quote":"The required fields are `migration_strategy`, with the values\n`inside_out_hard_break` and `fundamental_re_adoption`",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F6.%20Implementation%20migration%2FDeclaration%20and%20checklist",
          "start_line":790
        }
      ],
      "key":"migration_strategy",
      "label":"Migration strategy"
    },
    {
      "conditions": [],
      "definition": "A declared library_usage field, with none, consume and extend values, recording whether an active migration boundary rebuilds locally, consumes an existing reusable library/commonisation surface, or extends that surface before local implementation lands.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":855,
          "quote":"An implementation migration ticket declares whether the active boundary is\nrebuilding a pattern locally, consuming an existing reusable library or\ncommonisation surface, or extending that surface before the local\nimplementation lands; `library_usage` records which",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F6.%20Implementation%20migration%2FRecurring%20realisation%20and%20library%20declaration",
          "start_line":852
        }
      ],
      "key":"library_usage",
      "label":"Library usage declaration"
    },
    {
      "conditions": [
        "Core-interface, carrier or authoritative-contract migration."
      ],
      "definition": "A named walk of every live interface capable of bypassing, reinterpreting, replaying or projecting the migrating truth path, with interface-specific closure assertions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":938,
          "quote":"The checklist is a named walk of every live\ninterface that can still bypass, reinterpret, replay or project the\nmigrating truth path",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F6.%20Implementation%20migration%2FImpacted%20interface%20review%20checklist",
          "start_line":936
        }
      ],
      "key":"interface_review_checklist",
      "label":"Impacted Interface Review Checklist"
    },
    {
      "conditions": [
        "Implementation migration touches a core interface."
      ],
      "definition": "Required Break Order, or an equivalent ordered execution section, running outward from authoritative source truth: discover the full best-guess interface family; publish/admit the new carrier; deliberately sever and keep broken one old authoritative seam; rebind the deepest semantic kernel; remove/demote old producers; rebind old consumers; reprice projections, reports, prompts, delivery bindings and tests. With several old interfaces, a Break-To-Closure Map identifies the closure-law clause discharged by each break.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":985,
          "quote":"a `Break-To-Closure Map` stating which break closes which closure-law clause;",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F6.%20Implementation%20migration%2FBreak%20order%20and%20break-to-closure%20map",
          "start_line":984
        }
      ],
      "key":"migration_break_order",
      "label":"Migration break order and closure map"
    },
    {
      "conditions": [],
      "definition": "Assessment independent of the author of the exact reviewed subject, with subject, basis, scope, exclusions, evidence, verdict and unresolved findings identified. Authoring authority and independent verification authority differ.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1044,
          "quote":"Authority to author or implement a change is not independent authority to\nverify it.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FExecution%20and%20verification%20authority%20separation%20%28UP-007%29",
          "start_line":1037
        }
      ],
      "key":"independent_review",
      "label":"Independent assessment"
    },
    {
      "conditions": [
        "A residual judgment is needed by another activation."
      ],
      "definition": "A once-recorded judgment attached to its owning work in the existing selected carrier, identifying the question, exact subject and basis, supporting computed facts/evidence, responsible actor and authority, scoped conclusion, uncertainty and concrete revising observation. Rule-settled questions require no invented J record.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1103,
          "quote":"A residual judgment that another activation needs is recorded once, with\nits owning work, in the existing carrier selected under §5.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FRecorded%20judgment%20and%20owner-ruling%20continuity",
          "start_line":1095
        }
      ],
      "key":"recorded_judgment",
      "label":"Recorded residual judgment"
    },
    {
      "conditions": [],
      "definition": "A direct or lawfully proxied owner ruling retained in original wording with owner, exact subject and basis, permitted scope/effects, conditions and source, separately from agent interpretation. It is distinct from residual judgment.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1129,
          "quote":"A direct or lawfully proxied owner ruling is recorded in its original\nwording, with its owner, exact subject and basis, permitted scope and\neffects, conditions and source, separately from agent interpretation.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FRecorded%20judgment%20and%20owner-ruling%20continuity",
          "start_line":1122
        }
      ],
      "key":"owner_ruling",
      "label":"Owner ruling"
    },
    {
      "conditions": [],
      "definition": "The owner's separate authorized act establishing retained, superseded, deferred or withdrawn for an exact obligation, subject and basis. These four dispositions are lifecycle states without automatic core mappings. A material decision record identifies disposition, owner/grant, governing conditions, evidence, affected dependencies, remaining obligations and revisiting conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1152,
          "quote":"The four repricing dispositions are lifecycle states of an obligation,\nset by its owning authority. A state label is not an evaluation result and\nhas no automatic core mapping.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FRecorded%20judgment%20and%20owner-ruling%20continuity",
          "start_line":1145
        }
      ],
      "key":"repricing_decision",
      "label":"Material repricing decision"
    },
    {
      "conditions": [
        "An evaluation of the owner decision is actually performed."
      ],
      "definition": "Evaluation of whether the named owner lawfully establishes the disposition for the exact obligation, subject and basis, satisfying all applicable conditions and preserving every surviving obligation. repricing_established maps to satisfied; repricing_falsified to falsified; repricing_indeterminate to indeterminate; repricing_out_of_frame to out_of_frame; repricing_invalid_basis to invalid_basis. These concern repricing legality, not candidate acceptance or delivery.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1170,
          "quote":"| `repricing_indeterminate` | indeterminate | admissible evidence cannot decide whether the decision meets an applicable condition; the undecided condition and needed evidence remain explicit |",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FRecorded%20judgment%20and%20owner-ruling%20continuity",
          "start_line":1168
        }
      ],
      "key":"repricing_result",
      "label":"Repricing evaluation result"
    },
    {
      "conditions": [],
      "definition": "A bounded work claim with declared obligations, exact subject/basis/scope, required judgments and owner rulings, evidence and non-closure conditions. Its completion is condition-based; reviewer occurrence or a status label is not completion.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1189,
          "quote":"A work claim is complete only when every applicable declared obligation is\nsatisfied by valid evidence for its exact subject, basis and scope;",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FCondition-based%20closure%20and%20reuse",
          "start_line":1183
        }
      ],
      "key":"work_claim",
      "label":"Work claim"
    },
    {
      "conditions": [],
      "definition": "A proof projection from admitted work authority. A substantive test should derive through ticket, intake triage, lawful re-entry, and governing requirement/design/module/published function/carrier/closure surface to its expectation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1224,
          "quote":"Tests are proof projections from admitted work authority.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/TICKETS.md#TICKETS%2F7.%20Authority%2C%20judgment%2C%20closure%20and%20state%2FTest%20case%20authority",
          "start_line":1219
        }
      ],
      "key":"test_case",
      "label":"Ticket-local test case"
    },
    {
      "conditions": [],
      "definition": "F13 is the source's work-carrier derivation family, tracing carrier selection, claims and closure to commitments and instance premises: differing lifetimes, competing-looking surfaces, multiple tenants, migrations and variable carriers. Its table reports P0 as recovered; P1/P2/P3/P4a/P6 as independent; P4b as derived from P0/P2 under non-reacquirable step facts; P5 as derived from P0/P6 under an open-world premise. It distinguishes derived consequences from member choices and external owners; it does not itself decide the linked owners' questions.",
      "exceptions": [],
      "grounding": [
        {
